CREATE   PROCEDURE dbo.usp_merge_validation_scores      @payload NVARCHAR(MAX)  AS  BEGIN      SET NOCOUNT ON;      ;WITH src AS (          SELECT *          FROM OPENJSON(@payload, '$.rows')          WITH (              Customer                       NVARCHAR(100) '$."Customer"',              score_final                    FLOAT         '$.score_final',              Company_Code_Count             INT           '$.Company_Code_Count',              Sales_Org_Count                INT           '$.Sales_Org_Count',              Salesforce_Instance_Count      INT           '$.Salesforce_Instance_Count',              is_golden_record               BIT           '$.is_golden_record',              golden_record_id               NVARCHAR(100) '$.golden_record_id',              proposed_golden_id             NVARCHAR(100) '$.proposed_golden_id',              election_status                NVARCHAR(30)  '$.election_status',              approval_status                NVARCHAR(30)  '$.approval_status',              scored_with_weights_version    NVARCHAR(50)  '$.scored_with_weights_version',              score_SalesOrderLastUsed       FLOAT         '$.score_SalesOrderLastUsed',              score_SalesOrderCount          FLOAT         '$.score_SalesOrderCount',              score_SalesOrderPartnerLastUsed FLOAT        '$.score_SalesOrderPartnerLastUsed',              score_SalesOrderPartnerCount   FLOAT         '$.score_SalesOrderPartnerCount',              score_EquipmentCount           FLOAT         '$.score_EquipmentCount',              score_SleepingCustomer         FLOAT         '$.score_SleepingCustomer',              score_CustomerStatus           FLOAT         '$.score_CustomerStatus',              score_AccountGroup             FLOAT         '$.score_AccountGroup',              score_CompanyCodeCount         FLOAT         '$.score_CompanyCodeCount',              score_CombinedPresence         FLOAT         '$.score_CombinedPresence',              score_SalesforceInstances      FLOAT         '$.score_SalesforceInstances'          )      )      MERGE test_77.Validation AS tgt      USING src ON tgt.Customer = src.Customer      WHEN MATCHED THEN UPDATE SET          tgt.[score_final]                 = src.score_final,          tgt.[Company_Code_Count]          = src.Company_Code_Count,          tgt.[Sales_Org_Count]             = src.Sales_Org_Count,          tgt.[Salesforce_Instance_Count]   = src.Salesforce_Instance_Count,          tgt.[is_golden_record]            = src.is_golden_record,          tgt.[golden_record_id]            = src.golden_record_id,          tgt.[proposed_golden_id]          = src.proposed_golden_id,          tgt.[election_status]             = src.election_status,          tgt.[approval_status]             = src.approval_status,          tgt.[scored_with_weights_version] = src.scored_with_weights_version,          tgt.[score_SalesOrderLastUsed]        = src.score_SalesOrderLastUsed,          tgt.[score_SalesOrderCount]           = src.score_SalesOrderCount,          tgt.[score_SalesOrderPartnerLastUsed] = src.score_SalesOrderPartnerLastUsed,          tgt.[score_SalesOrderPartnerCount]    = src.score_SalesOrderPartnerCount,          tgt.[score_EquipmentCount]            = src.score_EquipmentCount,          tgt.[score_SleepingCustomer]          = src.score_SleepingCustomer,          tgt.[score_CustomerStatus]            = src.score_CustomerStatus,          tgt.[score_AccountGroup]              = src.score_AccountGroup,          tgt.[score_CompanyCodeCount]          = src.score_CompanyCodeCount,          tgt.[score_CombinedPresence]          = src.score_CombinedPresence,          tgt.[score_SalesforceInstances]       = src.score_SalesforceInstances;  END